const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const L = data[idx++];
const C = data[idx++];
const P = data[idx++];

const black = Array.from({ length: L }, () => Array(C).fill(false));

for (let i = 0; i < P; i++) {
  const x = data[idx++] - 1;
  const y = data[idx++] - 1;
  black[x][y] = true;
}

const dirs = [
  [-1, 0],
  [1, 0],
  [0, -1],
  [0, 1],
];

const allowedMask = Array(L).fill(0);

for (let r = 0; r < L; r++) {
  for (let c = 0; c < C; c++) {
    if (black[r][c]) continue;

    let ok = false;
    for (const [dr, dc] of dirs) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
        ok = true;
        break;
      }
    }

    if (ok) {
      allowedMask[r] |= 1 << c;
    }
  }
}

const maxMask = 1 << C;

const popcount = Array(maxMask).fill(0);
for (let m = 1; m < maxMask; m++) {
  popcount[m] = popcount[m >> 1] + (m & 1);
}

const validMasksPerRow = Array.from({ length: L }, () => []);

for (let r = 0; r < L; r++) {
  for (let mask = 0; mask < maxMask; mask++) {
    if ((mask & (mask << 1)) !== 0) continue;
    if ((mask & allowedMask[r]) !== mask) continue;
    validMasksPerRow[r].push(mask);
  }
}

let dp = Array(maxMask).fill(-1e9);
dp[0] = 0;

for (let r = 0; r < L; r++) {
  const ndp = Array(maxMask).fill(-1e9);

  for (let prev = 0; prev < maxMask; prev++) {
    if (dp[prev] < 0) continue;

    for (const curr of validMasksPerRow[r]) {
      if ((prev & curr) === 0) {
        const val = dp[prev] + popcount[curr];
        if (val > ndp[curr]) {
          ndp[curr] = val;
        }
      }
    }
  }

  dp = ndp;
}

let answer = 0;
for (let mask = 0; mask < maxMask; mask++) {
  if (dp[mask] > answer) answer = dp[mask];
}

console.log(answer);
